<?php $title='Systemupdates'; ?>
<div class="page-header split"><div><p class="eyebrow">Administration · Updates</p><h1>Systemupdates</h1><p>Produktiver Update-Stand: öffentlicher GitHub-Branch <code>main</code>. Kein GitHub-Token erforderlich.</p></div><form method="post" action="<?= e(url('admin/updates/check')) ?>"><?= csrf_field() ?><button class="button ghost" type="submit">Nach Update suchen</button></form></div>
<?php if($error):?><div class="notice error"><?= e($error) ?></div><?php elseif($remote):?><div class="panel"><div class="detail-grid"><div class="detail-item"><small>Installierte Version</small><strong><?= e($remote['local_version']) ?></strong></div><div class="detail-item"><small>Version auf main</small><strong><?= e($remote['remote_version']) ?></strong></div><div class="detail-item"><small>Remote Commit</small><strong><code><?= e(substr($remote['remote_sha'],0,12)) ?></code></strong></div><div class="detail-item wide"><small>Letzter Commit</small><div><?= e($remote['commit_message']??'–') ?></div></div></div><?php if($remote['update_available']):?><form method="post" action="<?= e(url('admin/updates/install')) ?>" class="form-actions"><?= csrf_field() ?><button class="button primary" type="submit">Update installieren</button></form><?php else:?><div class="notice success">Kein neuer veröffentlichter Versionsstand erkannt.</div><?php endif;?></div><?php endif;?>
<div class="panel"><div class="panel-header"><div><h2>Datenbankmigrationen</h2><p>Ausstehende versionierte Migrationen.</p></div><?php if($pending):?><form method="post" action="<?= e(url('admin/updates/migrate')) ?>"><?= csrf_field() ?><button class="button secondary" type="submit">Migrationen ausführen</button></form><?php endif;?></div><?php if($pending):?><ul><?php foreach($pending as $m):?><li><code><?= e($m) ?></code></li><?php endforeach;?></ul><?php else:?><p class="muted">Keine ausstehenden Migrationen.</p><?php endif;?></div>
<div class="panel"><h2>Update-Historie</h2><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Version</th><th>Commit</th><th>Status</th><th>Benutzer</th><th>Fehler</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?= e(format_datetime($h['occurred_at'])) ?></td><td><?= e($h['version']) ?></td><td><code><?= e($h['commit_sha']?substr($h['commit_sha'],0,12):'–') ?></code></td><td><span class="badge <?= $h['status']==='successful'?'active':($h['status']==='failed'?'warning':'neutral') ?>"><?= e($h['status']) ?></span></td><td><?= e($h['user_name']??'–') ?></td><td><?= e($h['error_message']??'') ?></td></tr><?php endforeach;?><?php if($history===[]):?><tr><td colspan="6" class="empty">Noch keine Updates über das Adminsystem installiert.</td></tr><?php endif;?></tbody></table></div></div>
